// Wave shape: Colliders
// Macro:  Wave(Colliders, "Erlend Robaye", "", "", 10)
// Source: pixel/PartiShort.sky.h:70
// Author: Erlend Robaye
// Steps=2  Aspect=1  Instances(num)=10
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(4) Density(3)
// ==============================================================================
void wave_Colliders(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(2);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = rnd(.3) + .2;  // Scaling speed
    a[1] = t;
    a[2] = 1.5;  // Size of line
    a[3] = 2*a[2];
    a[4] = rnd(.5) + .2;  // Rotation speed circle
    a[5] = 5;  // Number of points in circle
    a[6] = rnd(.3) + .1;  // Global rotation speed
    a[7] = 3 + rnd( 7 );
    a[8] = .05 + rnd( .5 );  // Dot intensity

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sin(t*a[0]);
    b[1] = (sgn(b[0]) + 1 )* .5;  // O when < 0) 1 when >0
    b[2] = dabs(b[1]-1);  // 1 when < 0) 0 when >0
    b[3] = t * a[4];
    b[4] = cos(b[3]);
    b[5] = sin(b[3]);
    b[18] = -t*a[6];
    b[19] = cos(b[18]);
    b[20] = sin(b[18]);
    b[6] = b[3] + 2*PI/a[5];
    b[7] = cos(b[6]);
    b[8] = sin(b[6]);
    b[9] = b[3] + 4*PI/a[5];
    b[10] = cos(b[9]);
    b[11] = sin(b[9]);
    b[12] = b[3] + 6*PI/a[5];
    b[13] = cos(b[12]);
    b[14] = sin(b[12]);
    b[15] = b[3] + 8*PI/a[5];
    b[16] = cos(b[15]);
    b[17] = sin(b[15]);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = b[0] * (-a[2] + s*a[3]);  // Line
        c[1] = -1 + id * (2/num);  // Y pos differs for each instance
        c[2] = .5 * c[0];  // Half a line size for the rotating line (after collision)
        c[3] = c[1] + sin(t*8) * .1;  // sin on pos Y of line before collision
        c[4] = -b[5] * c[2];  // For rotating line Y(c1 has to be 0 before the rotation
        c[5] = ( b[4] * c[2]         ) + c[1];
        c[6] = c[0] * b[1] + c[4] * b[2];
        c[7] = c[3] * b[1] + c[5] * b[2];
        x[0] = -b[19] * c[7] -b[20] * c[6]; xyiMax = max(xyiMax, 0);
        y[0] = b[19] * c[6] -b[20] * c[7];
        c[8] = -b[8] * c[2];  // For rotating line Y(c1 has to be 0 before the rotation
        c[9] = ( b[7] * c[2]         ) + c[1];
        c[10] = c[0] * b[1] + c[8] * b[2];
        c[11] = c[3] * b[1] + c[9] * b[2];
        x[1] = -b[19] * c[11] -b[20] * c[10]; xyiMax = max(xyiMax, 1);
        y[1] = b[19] * c[10] -b[20] * c[11];
        c[12] = -b[11] * c[2];  // For rotating line Y(c1 has to be 0 before the rotation
        c[13] = (b[10] * c[2]) + c[1];
        c[14] = c[0] * b[1] + c[12] * b[2];
        c[15] = c[3] * b[1] + c[13] * b[2];
        x[2] = -b[19] * c[15] -b[20] * c[14]; xyiMax = max(xyiMax, 2);
        y[2] = b[19] * c[14] -b[20] * c[15];
        c[16] = -b[14] * c[2];  // For rotating line Y(c1 has to be 0 before the rotation
        c[17] = ( b[13] * c[2]) + c[1];
        c[18] = c[0] * b[1] + c[16] * b[2];
        c[19] = c[3] * b[1] + c[17] * b[2];
        x[3] = -b[19] * c[19] -b[20] * c[18]; xyiMax = max(xyiMax, 3);
        y[3] = b[19] * c[18] -b[20] * c[19];
        c[20] = -b[17] * c[2];  // For rotating line Y(c1 has to be 0 before the rotation
        c[21] = ( b[16] * c[2]) + c[1];
        c[22] = c[0] * b[1] + c[20] * b[2];
        c[23] = c[3] * b[1] + c[21] * b[2];
        x[4] = -b[19] * c[23] -b[20] * c[22]; xyiMax = max(xyiMax, 4);
        y[4] = b[19] * c[22] -b[20] * c[23];
        draw(0, a[7], a[8], x, y, xyiMax);  // Meta() Reactive(1) Detail(4) Density(3)
    }
}

