// Wave shape: Dancing_String
// Macro:  Wave(Dancing_String, "Thomas Geier", "ziggystar(at)gmx.de", "", 1)
// Source: pixel/PartiShort.sky.h:170
// Author: Thomas Geier  <ziggystar(at)gmx.de>
// Steps=300  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(3)
// ==============================================================================
void wave_Dancing_String(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(300);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 0.1;  // nothing
    a[1] = 0.7;  // size
    a[2] = trnc( 1 + rnd( 1.99 ) );  // line width
    a[3] = .1 + rnd( .7 );  // Pen darkness

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = .4 * t;  // time scale
    b[1] = 6.28*(1.3+sin(b[0]*0.414));
    b[2] = 6.28*(1.3+sin(b[0]*0.628));
    b[3] = b[0]*1.2754;
    b[4] = b[0]*1.435;
    b[5] = b[0]*1.643;

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        x[0] = a[1]*cos(s*b[1])*sqrt(0.2*pow(sin(s*3.80+b[4]),2) +    pow(cos(s*6.28+b[3]),2)); xyiMax = max(xyiMax, 0);
        y[0] = a[1]*sin(s*b[2])*sqrt(    pow(sin(s*6.28+b[5]),2) +0.2*pow(cos(s*6.28+b[0]),2));
        draw(1, a[2], a[3], x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
}

// ==============================================================================
// Wave shape: Orbiting_Rods_N_Sticks
// Macro:  Wave(Orbiting_Rods_N_Sticks, "Andy O'Meara", "", "Orbiting Rods - inspired by Erlend Robaye", (int)(8+rnd(18.1)))
// Source: pixel/PartiShort.sky.h:195
// Author: Andy O'Meara
// Note:   Orbiting Rods - inspired by Erlend Robaye
// Steps=2  Aspect=1  Instances(num)=(int)(8+rnd(18.1))
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(2) Density(3) Zoomable(4)
// ==============================================================================
void wave_Orbiting_Rods_N_Sticks(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(2);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .5  + rnd(.6);
    a[1] = -.08 - rnd(.4);  // orbit rotation rate
    a[2] = .08*(1+rnd(4) );  // segment length
    a[3] = .3  + rnd(2.2);
    a[4] = rnd( 4.1 );  // Rod width

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = a[1] * t + 2 * PI * ( id / num );  // theta from (0)0)
    b[1] = a[3] * t;  // theta from center of rod

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = a[2] * ( s - .5 ) * cos( b[1] ) + a[0];  // x'
        c[1] = a[2] * ( s - .5 ) * sin( b[1] );  // y'
        x[0] = c[0] * cos( b[0] ) - c[1] * sin( b[0] ); xyiMax = max(xyiMax, 0);
        y[0] = c[1] * cos( b[0] ) + c[0] * sin( b[0] );
        draw(1, a[4], 1, x, y, xyiMax);  // Meta() Reactive(1) Detail(2) Density(3) Zoomable(4)
    }
}

// ==============================================================================
// Wave shape: Miris_Ball
// Macro:  Wave(Miris_Ball, "Jeff Osborn", "jo009j(at)mail.rochester.edu", "", (int)(rnd(5)+8))
// Source: pixel/PartiShort.sky.h:217
// Author: Jeff Osborn  <jo009j(at)mail.rochester.edu>
// Steps=num + (num - id)  Aspect=1  Instances(num)=(int)(rnd(5)+8)
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(1)
// NOTE(port): Steps/Aspect reference `id`, but the real engine evaluates
// them once per shape-selection inside a shared (non-per-instance) member,
// so only the LAST instance's (id == num-1) value actually takes effect.
// ==============================================================================
void wave_Miris_Ball(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(num + (num - id));
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = rnd(0.3) + 0.1;  // Random initial radius
    a[1] = rnd(.9);  // This is used to calcluate the path the entire ball travels
    a[2] = rnd(.9);  // So is this
    a[3] = clip( .3 + rnd( .9 ) );  // Random pen darkness

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * a[1];  // This helps make the circles spin..the dots) that is.  The dots spin _along_ the cirlce) this has nothing to do with the psuedo-3D motion  ",1)
    b[1] = sin(t * a[1]);  // The path of the entire ball
    b[2] = sin(t * a[2]);  // Same
    b[3] = id / num;  // The unique id of each pair of circles.
    b[4] = b[3] * a[0] * sin(.8 * t);
    b[5] = b[3] * a[0] * cos(.8 * t);
    b[6] = (a[0] - (a[0] * b[3])) * cos(.8 * t);  // radius in Y) after calculations and spinning
    b[7] = (a[0] - (a[0] * b[3])) * sin(.8 * t);  // radius in X) after calculations and spinning

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = b[7] * cos( s * PI*2 + b[0] ) + b[1];
        c[1] = b[6] * sin( s * PI*2 + b[0] ) + b[2];
        x[0] = ( c[0] + b[5] ) * .54; xyiMax = max(xyiMax, 0);
        y[0] = ( c[1] + b[4] ) * .84;
        x[1] = ( c[0] - b[5] ) * .54; xyiMax = max(xyiMax, 1);
        y[1] = ( c[1] - b[4] ) * .84;
        draw(0, 1, a[3], x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(1)
    }
}

// ==============================================================================
// Wave shape: Waves
// Macro:  Wave(Waves, "Erlend Robaye", "", "", 1)
// Source: pixel/PartiShort.sky.h:253
// Author: Erlend Robaye
// Steps=20  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(3)
// ==============================================================================
void wave_Waves(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(20);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 3*PI;
    a[1] = rnd(.6)+.3;  // Amplitude
    a[2] = .8;  // scaling factor next waves
    a[3] = rnd(.3) + .2;  // Rotation speed
    a[4] = rnd(1.5) + 1;  // Sine move speed
    a[5] = rnd( 5 ) + 1;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = a[3]*t;
    b[1] = cos(b[0]);
    b[2] = sin(b[0]);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = -1 + s*2;
        c[1] = -.2 + a[1] * sin(s*a[0]+t*a[4]);
        c[2] = -b[1] * c[1] -b[2] * c[0];
        c[3] = b[1] * c[0] -b[2] * c[1];
        x[1] = pow(a[2],1)*c[2]; y[1] = pow(a[2],1)*c[3]; xyiMax = max(xyiMax, 1);
        x[2] = pow(a[2],2)*c[2]; y[2] = pow(a[2],2)*c[3]; xyiMax = max(xyiMax, 2);
        x[3] = pow(a[2],3)*c[2]; y[3] = pow(a[2],3)*c[3]; xyiMax = max(xyiMax, 3);
        x[4] = pow(a[2],4)*c[2]; y[4] = pow(a[2],4)*c[3]; xyiMax = max(xyiMax, 4);
        x[5] = pow(a[2],5)*c[2]; y[5] = pow(a[2],5)*c[3]; xyiMax = max(xyiMax, 5);
        x[6] = pow(a[2],6)*c[2]; y[6] = pow(a[2],6)*c[3]; xyiMax = max(xyiMax, 6);
        x[7] = pow(a[2],7)*c[2]; y[7] = pow(a[2],7)*c[3]; xyiMax = max(xyiMax, 7);
        x[8] = pow(a[2],8)*c[2]; y[8] = pow(a[2],8)*c[3]; xyiMax = max(xyiMax, 8);
        x[0] = pow(a[2],9)*c[2]; y[0] = pow(a[2],9)*c[3]; xyiMax = max(xyiMax, 0);
        draw(0, ux*20*mag(s), .5+uy, x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
}

// ==============================================================================
// Wave shape: DNA_String
// Macro:  Wave(DNA_String, "Erlend Robaye", "", "", 1)
// Source: pixel/PartiShort.sky.h:287
// Author: Erlend Robaye
// Steps=200  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(4) Density(3)
// ==============================================================================
void wave_DNA_String(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(200);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 4;
    a[1] = sampleSteps()/a[0];  // Number of DNA segments
    a[2] = PI/4;
    a[3] = 2*a[2];
    a[4] = a[3]/a[1];
    a[5] = rnd(.4) + .4;  // Size one segment
    a[6] = a[5]/(a[0]-1);
    a[7] = a[5]/2;
    a[8] = 6;
    a[9] = a[8] * ( .9 );
    a[11] = rnd(.4) - .2;
    a[12] = (rnd(1)  + .5) * sgn(rnd(1)-.5);  // Rotation speed dna-string around its axis
    a[16] = .7 + rnd(.4);  // Pen

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[10] = PI/2 + .3;
    b[13] = .25+ux;  // Twisting factor for each next segment
    b[14] = cos(b[10]);
    b[15] = sin(b[10]);
    b[0] = t*a[11];
    b[1] = cos(b[0]);
    b[2] = sin(b[0]);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = trnc(s * sampleSteps()/a[0]);
        c[1] = trnc(s * sampleSteps()) - (a[0] * c[0]);  // Nr of particle withing segment 0..(a0-1)
        c[2] = -a[7] + (c[1] * a[6]);  // X position) y(0
        c[3] = (t * a[12]) + (c[0]*b[13]);
        c[4] = -sin(c[3])*c[2];  // X
        c[5] = cos(c[3])*c[2];  // Y
        c[6] = c[5] * b[14];  // Y'(          Y * cos(camera)
        c[7] = a[8] - c[5] * b[15];  // Z (Distort - Y * sin(camera)
        c[8] = a[9] * c[4] / c[7];
        c[9] = ( a[9] * c[6] / c[7] ) - a[2] + c[0] * a[4];  // SizeMix * Y' / Z) add Y per id) Add Y inc per segment
        x[0] = -b[1]*c[9]-b[2]*c[8]; xyiMax = max(xyiMax, 0);
        y[0] = b[1]*c[8]-b[2]*c[9];
        draw(0, (40 - (( c[7] - 5 ) * 36)), a[16], x, y, xyiMax);  // Meta() Reactive(1) Detail(4) Density(3)
    }
}

// ==============================================================================
// Wave shape: Sea_Surface
// Macro:  Wave(Sea_Surface, "Erlend Robaye", "erlend(at)vt4.net", "", 1)
// Source: pixel/PartiShort.sky.h:343
// Author: Erlend Robaye  <erlend(at)vt4.net>
// Steps=sqr(flor(15+ rnd(15) ) )  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(5) Density(4)
// ==============================================================================
void wave_Sea_Surface(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(sqr(flor(15+ rnd(15) ) ));
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = trnc( sqrt( sampleSteps() ) );
    a[1] = rnd( 2 * PI );
    a[2] = ( .6 + rnd( 1 ) ) * cos( a[1] );
    a[3] = ( .6 + rnd( 1 ) ) * sin( a[1] );
    a[4] = 6;
    a[5] = a[4] * 1.2;
    a[6] = 1.8 + rnd( .5 );
    a[7] = .6 + rnd(.4);

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t*.15;
    b[1] = cos(b[0]);
    b[2] = sin(b[0]);
    b[3] = sin( a[6] );
    b[4] = cos( a[6] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = 2*( fmod(s*sampleSteps()-1 ,a[0]))/a[0]-1;  // X
        c[1] = 2*(trnc((s*sampleSteps()-1)/a[0]))/a[0]-1;  // Y
        c[2] = .18*sin(6*c[0]+a[2]*t)*cos(6*c[1]+a[3]*t);  // Z
        c[3] = -b[1]*c[1]-b[2]*c[0];  // X'
        c[4] = b[1]*c[0]-b[2]*c[1];  // Y'
        c[5] = c[4] * b[4] + c[2] * b[3];  // Y' (     Y * cos( a ) + Z * sin( a )
        c[6] = a[4]  - c[4] * b[3] + c[2] * b[4];  // Z' ( D - Y * sin( a ) + Z * cos( a )
        x[0] = a[5] * c[3] / c[6]; xyiMax = max(xyiMax, 0);  // NewX ( SizeMix * X / Z
        y[0] = a[5] * c[5] / c[6];  // NewY ( SizeMix * Y / Z
        draw(0, ux*(35 - 5*c[6]), .5+uy, x, y, xyiMax);  // Meta() Reactive(1) Detail(5) Density(4)
    }
}

