// ==============================================================================
// Wave shape: Protozoan_Lovers
// Macro:  Wave(Protozoan_Lovers, "Jeff Osborn", "jo009j(at)mail.rochester.edu", "", (int)(rnd(2.5)+1))
// Source: pixel/PartiShort.sky.h:442
// Author: Jeff Osborn  <jo009j(at)mail.rochester.edu>
// Steps=rnd(3) + 9  Aspect=0  Instances(num)=(int)(rnd(2.5)+1)
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(4) Density(1)
// ==============================================================================
void wave_Protozoan_Lovers(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(rnd(3) + 9);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = t;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = seed( a[0] * ( id / num + 5.5 ) );
    b[1] = rnd(0.8) + 0.2;  // These decide the path for the protozoa
    b[2] = rnd(0.8) + 0.2;

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = .8 * t - s / 2;
        x[0] = (sin(c[0] * b[1])) * 0.90 + sin(c[0] * 5) * 0.075; xyiMax = max(xyiMax, 0);
        y[0] = (cos(c[0] * b[2])) * 0.90 + cos(c[0] * 6) * 0.075;
        draw(0, (9-(s*4)), (1.2-s), x, y, xyiMax);  // Meta() Reactive(1) Detail(4) Density(1)
    }
}

// ==============================================================================
// Wave shape: Snakes
// Macro:  Wave(Snakes, "Thomas Geier", "ziggystar(at)gmx.de", "", (int)(5+rnd(10)))
// Source: pixel/PartiShort.sky.h:463
// Author: Thomas Geier  <ziggystar(at)gmx.de>
// Steps=50  Aspect=1  Instances(num)=(int)(5+rnd(10))
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(3)
// ==============================================================================
void wave_Snakes(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(50);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = t;  // should be clear
    a[1] = timeEnd()-t;  // the same

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[1] = ux*32;

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = seed(a[0]*id);
        c[1] = rnd(2)-1;  // x Position
        c[2] = rnd(.3)+.2;  // length
        c[3] = rnd(1);  // Offset until appearance
        c[4] = rnd(3.141);  // movement offset
        c[5] = 2*(t-a[0])/b[1]-c[3]-s*c[2];
        c[6] = ( c[1]+0.14*sin(18*c[5]/c[2]+t*8+c[4])*c[2] ) * 3.141;  // theta
        c[7] = pos(c[5])*2;
        x[0] = cos(c[6])*c[7]; xyiMax = max(xyiMax, 0);
        y[0] = sin(c[6])*c[7];
        draw(1, (10*c[2]*(1-s)+1)*(c[7]+0.3), .6, x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
}

