// Wave shape: Crosshatch
// Macro:  Wave(Crosshatch, "Ted", "", "", 1)
// Source: pixel/PartiShort.sky.h:617
// Author: Ted
// Steps=300  Aspect=0  Instances(num)=1
// Duration=10 + rnd( 10 ) seconds (overrides default auto-advance timer)
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(3)
// ==============================================================================
void wave_Crosshatch(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(300);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    double duration = (10 + rnd( 10 ));  // seconds
    a[0] = rnd(PI-1)+2;
    a[1] = rnd(8)+2;
    a[2] = sgn(rnd(2)-1);
    a[3] = rnd(3)+2;
    a[4] = rnd(3)+2;
    a[5] = trnc(rnd(3))+1;
    a[6] = .04 + rnd( .1 );  // Line brightness

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    // (no B() frame terms)

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = s*a[1]+t/a[3];
        c[1] = trwv(c[0]);
        c[2] = sin(a[0]*c[0]+t/a[4]);
        x[0] = c[1]; xyiMax = max(xyiMax, 0);
        y[0] = c[2];
        x[1] = -c[1]; xyiMax = max(xyiMax, 1);
        y[1] = a[2]*c[2];
        draw(1, 1, a[6], x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
}

// ==============================================================================
// Wave shape: Juggler
// Macro:  Wave(Juggler, "Ted", "", " Orbiting Rods", (int)(2+rnd(16)))
// Source: pixel/PartiShort.sky.h:643
// Author: Ted
// Note:    Orbiting Rods
// Steps=2  Aspect=1  Instances(num)=(int)(2+rnd(16))
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(2) Density(3)
// ==============================================================================
void wave_Juggler(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(2);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .4+rnd(.6);
    a[1] = sgn(rnd(2)-1)*(.1+rnd(.3));
    a[2] = .08*(1+rnd(7));
    a[3] = sgn(rnd(2)-1)*(.5+rnd(1));
    a[4] = trnc(rnd(16)*4+4)*PI/num;  // swoosh factor
    a[5] = 1;
    a[6] = clip( .3 + rnd(.7) );

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = a[1]*t+2*PI*(id/num);
    b[1] = a[3]*t;
    b[2] = a[0]*sin(t/2+a[4]*id);
    b[3] = a[2]*sin(t/2+a[4]*id);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = b[3]*(s-.5)*cos(b[1])+b[2];
        c[1] = b[3]*(s-.5)*sin(b[1]);
        x[0] = c[0]*cos(b[0])-c[1]*sin(b[0]); xyiMax = max(xyiMax, 0);
        y[0] = c[1]*cos(b[0])+c[0]*sin(b[0]);
        draw(1, a[5], 1, x, y, xyiMax);  // Meta() Reactive(1) Detail(2) Density(3)
    }
}
